// План: specs/disputes.md, блок 6 (6.1). Кейс: .qa/tests/disputes/DSP-012.md (#8757b4).
// Несколько ролей: клиент открывает спор «בורר אנושי» по сделке ₪1, נותן שירות соглашается, арбитр решает 0.5/0.5,
// клиент подтверждает ПЕРВЫМ и остаётся на экране предложения, поставщик подтверждает —
// у клиента без перезагрузки после «חזרה» сделка «הושלמה», в списке её нет под «במחלוקת», есть под «הושלמו».
// Меняет деньги тестовых аккаунтов (сделка ₪1 + сбор ₪150 за בורר с открывающего) → @data, флаги QA_ALLOW_DEPOSIT=1 и QA_ALLOW_ARBITER_FEE=1.
// Записан 04.11 без прогона: селекторы чипов фильтра «עסקאות» и строки сделки подтвердить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { getEscrowDeal, openArbiterDispute, openTab, waitWithReload } from './helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

const AMOUNT = 1; // ₪ сделки
const RELEASE = '0.5'; // ₪ נותן/ת השירות; столько же — обратно משלם/ת

/** Сторона открывает решение арбитра на вкладке «מחלוקת» сделки. */
async function openArbiterProposal(page: Page, dealId: string) {
  await page.goto(`/deals/${dealId}?tab=dispute`);
  const view = page.getByRole('button', { name: /צפייה בהצעת/ });
  const title = page.getByText('הצעת פתרון בעזרת בורר אנושי').first();
  await waitWithReload(page, view.or(title));
  if (await view.first().isVisible().catch(() => false)) await view.first().click();
  await expect(title).toBeVisible();
}

/** Чип фильтра списка «עסקאות» (верхний ряд — первый с таким текстом). */
function chip(page: Page, name: 'במחלוקת' | 'הושלמו') {
  return page.getByText(name, { exact: true }).first();
}

/** Список «עסקאות»: под «במחלוקת» сделки нет, под «הושלמו» — есть. */
async function expectMovedToCompleted(page: Page, title: string) {
  await expect(page.getByTestId('deals-title')).toBeVisible();
  await chip(page, 'במחלוקת').click();
  await expect(page.getByText(title)).toHaveCount(0);
  await chip(page, 'הושלמו').click();
  await expect(page.getByText(title).first()).toBeVisible();
}

test.describe('מחלוקות — בורר אנושי: אחרי אישור שני הצדדים העסקה הושלמה', () => {
  test('לקוח מאשר ראשון ונשאר במסך → נותן השירות מאשר → "חזרה": "הושלמה", לא ב"במחלוקת", כן ב"הושלמו", ביומן "המחלוקת הוכרעה" @iphone @data #8757b4', async ({ asUser }) => {
    test.skip(
      process.env.QA_ALLOW_ARBITER_FEE !== '1',
      'Спор «בורר אנושי» списывает сбор ₪150 с тестового баланса — задай QA_ALLOW_ARBITER_FEE=1 (решение пользователя).',
    );
    const client = await asUser('client');
    const provider = await asUser('provider');
    const arbitrator = await asUser('arbitrator');

    const { id, title } = await getEscrowDeal(client, provider, 'ARBITER_DONE', AMOUNT);
    test.skip(!title, 'Для проверки фильтров нужно название сделки — сделка из QA_DISPUTE_DEAL_ARBITER_DONE без названия не подходит.');

    // 1. Клиент открывает спор с בורר אנושי.
    await openArbiterDispute(client, id);

    // 2. נותן שירות соглашается на בורר אנושי.
    await provider.goto(`/deals/${id}?tab=dispute`);
    await waitWithReload(provider, provider.getByText('האם את/ה מאשר גישור בעזרת בורר אנושי?'));
    await provider.getByRole('button', { name: /^אישור/ }).first().click();
    const feeConfirm = provider.getByRole('button', { name: /תשלום|אישור ותשלום|המשך/ }).last();
    if (await feeConfirm.isVisible().catch(() => false)) await feeConfirm.click();

    // 3. Арбитр: решение 0.5 / 0.5.
    await arbitrator.goto('/arbitration');
    await expect(arbitrator.getByText('מחלוקות לבוררות').first()).toBeVisible();
    const row = arbitrator.getByRole('button').filter({ hasText: title }).filter({ hasText: 'ממתין להחלטתך' });
    await waitWithReload(arbitrator, row);
    await row.first().click();
    await arbitrator.waitForURL(/\/arbitration\/[0-9a-f-]{20,}/);
    await arbitrator.getByRole('textbox', { name: /כמה לשחרר לנותן\/ת השירות/ }).fill(RELEASE);
    await arbitrator.getByRole('textbox', { name: 'נימוק' }).fill('QA-AUTO: החלטת בורר אוטומטית — פיצול 0.5/0.5.');
    await expect(arbitrator.getByText(/לשחרר ₪0\.50? לנותן\/ת השירות ולהחזיר ₪0\.50? למשלם\/ת\./)).toBeVisible();
    const send = arbitrator.getByRole('button', { name: 'שליחת ההחלטה לשני הצדדים' });
    await expect(send).not.toHaveAttribute('aria-disabled', 'true');
    await send.click();

    // 4. Клиент доходит до предложения как пользователь: «עסקאות» → «במחלוקת» → сделка → «מחלוקת» → предложение.
    await client.goto('/deals');
    await expect(client.getByTestId('deals-title')).toBeVisible();
    await chip(client, 'במחלוקת').click();
    await waitWithReload(client, client.getByText(title));
    await client.getByText(title).first().click();
    await client.waitForURL(new RegExp(`/deals/${id}`));
    await openTab(client, 'מחלוקת');
    const view = client.getByRole('button', { name: /צפייה בהצעת/ });
    const proposalTitle = client.getByText('הצעת פתרון בעזרת בורר אנושי').first();
    await waitWithReload(client, view.or(proposalTitle));
    if (await view.first().isVisible().catch(() => false)) await view.first().click();
    await expect(proposalTitle).toBeVisible();

    // Клиент подтверждает ПЕРВЫМ — состояние ожидания, повторно подтвердить нельзя (F-54 AC11).
    await client.getByRole('button', { name: 'אישור ההצעה' }).click();
    await expect(client.getByText(/אישרת את ההצעה/).first()).toBeVisible();
    await expect(client.getByText(/ממתין לצד השני/).first()).toBeVisible();
    await expect(client.getByRole('button', { name: 'אישור ההצעה' })).toHaveCount(0);

    // 5. Поставщик подтверждает вторым. Клиентскую страницу НЕ обновляем.
    await openArbiterProposal(provider, id);
    await provider.getByRole('button', { name: 'אישור ההצעה' }).click();

    // Панель арбитра — решение принято обеими сторонами (DSP-010).
    await arbitrator.goto('/arbitration');
    await waitWithReload(
      arbitrator,
      arbitrator.getByRole('button').filter({ hasText: title }).filter({ hasText: 'ההצעה אושרה על ידי שני הצדדים' }),
    );

    // 6. Клиент без перезагрузки: «חזרה» → экран сделки «הושלמה» (суть фикса #8757b4).
    await client.getByTestId('back-button').first().click();
    await expect(client.getByText(/הושלמה/).first()).toBeVisible({ timeout: 30_000 });

    // «חזרה» до списка «עסקאות» (из вкладки «מחלוקת» может понадобиться ещё один шаг).
    for (let i = 0; i < 3 && !(await client.getByTestId('deals-title').isVisible().catch(() => false)); i++) {
      await client.getByTestId('back-button').first().click();
    }
    await expectMovedToCompleted(client, title);

    // 7. У поставщика то же (тикет: «שני הצדדים»).
    await provider.goto('/deals');
    await expectMovedToCompleted(provider, title);

    // 8. «היסטוריה» у обеих сторон — «המחלוקת הוכרעה» (DSP-008).
    for (const page of [client, provider]) {
      await page.goto(`/deals/${id}`);
      await expect(page.getByText(/הושלמה/).first()).toBeVisible();
      await openTab(page, 'היסטוריה');
      await waitWithReload(page, page.getByText('המחלוקת הוכרעה').first());
    }
  });
});
